29	    "46.pre": {
30	      "tilaka": "संवृताकारो निगृहीतान्तर्गतभयः । उत्तमां मतिं धैर्यविषयाम् ।। 5.46.1,2 ।।\n\nहनूमद्ग्रहणे सन्दिदेश । व्यग्रान्सर्वत्र कार्ये त्वरावतः",
31	      "bhusana": "हतान् मन्त्रिसुतान् बुद्ध्वा वानरेण महात्मना ।\n\nरावणः संवृताकारश्चकार मतिमुत्तमाम्",
32	      "siromani": "मन्त्रिसुतवधानन्तरकालिकं रावणवृत्तान्तमाह हतानित्यादिभिः । मन्त्रिसुतान्वानरेण हतान् बुद्धा संवृतः आच्छादितः आकारः पूर्वाकृतिर्येन सः भीतियुक्ताकृतिविशिष्ट इत्यर्थः । किंच संवृतः स्वीकृतः आकारः प्राप्तकिंचिद्भीतिहेतुकाकृतिर्येन स रावणः उत्तमां मतिं पुनर्युद्धनिश्चयमित्यर्थः । चकार"
33	    }
34	  },
35	  "verses": [
36	    {
37	      "verse_id": "5.46.1",
38	      "sarga": 46,
39	      "verse": "1",
40	      "ambiguous_marker": false,
41	      "sanskrit_iast": "hatān mantrisutān buddhvā vānareṇa mahātmanā । rāvaṇaḥ saṃvṛtākāraś cakāra matim uttamām ॥1॥",
42	      "leonov_ru": "Узнав, что убиты сыновья советников великой духом обезьяной, Равана, скрыв свои чувства, придумал новое решение.",
43	      "commentary": {
44	        "bhusana": "हतान् मन्त्रिसुतान् बुद्ध्वा वानरेण महात्मना ।\n\nरावणः संवृताकारश्चकार मतिमुत्तमाम्\nहतानित्यादि । संवृताकारः अन्तर्मनाः । मतिं चिन्ताम्",
45	        "siromani": "मन्त्रिसुतवधानन्तरकालिकं रावणवृत्तान्तमाह हतानित्यादिभिः । मन्त्रिसुतान्वानरेण हतान् बुद्धा संवृतः आच्छादितः आकारः पूर्वाकृतिर्येन सः भीतियुक्ताकृतिविशिष्ट इत्यर्थः । किंच संवृतः स्वीकृतः आकारः प्राप्तकिंचिद्भीतिहेतुकाकृतिर्येन स रावणः उत्तमां मतिं पुनर्युद्धनिश्चयमित्यर्थः । चकार"
46	      },
47	      "pratika_check": {
