59	      "verse_id": "5.46.2",
60	      "sarga": 46,
61	      "verse": "2",
62	      "ambiguous_marker": false,
63	      "sanskrit_iast": "sa virūpākṣayūpākṣau durdharaṃ caiva rākṣasaṃ । praghasaṃ bhāsakarṇaṃ ca pañca senāgranāyakān ॥2॥",
64	      "leonov_ru": "Пять полководцев – Вирупакшу и Юпакшу, А также ракшаса Дурдхару, Прагхасу и Бхасакарну",
65	      "commentary": {
66	        "bhusana": "स विरूपाक्षयूपाक्षौ दुर्धरं चैव राक्षसम् ।\n\nप्रघसं भारकर्णं च पञ्च सेनाग्रनायकान्"
67	      },
68	      "pratika_check": {
69	        "bhusana": {
70	          "pratika_iast": "sa virupaksayupaksau durdharan caiva",
71	          "matches_verse": true
72	        }
73	      }
74	    },
75	    {
76	      "verse_id": "5.46.3",
77	      "sarga": 46,
78	      "verse": "3",
79	      "ambiguous_marker": false,
80	      "sanskrit_iast": "saṃdideśa daśagrīvo vīrān nayaviśāradān । hanūmadgrahaṇe 'vyagrān vāyuvegasamān yudhi ॥3॥",
81	      "leonov_ru": "Отважных, искусных в управлении (войсками), не теряющих спокойствия и быстрых в битве подобно ветру, Послал Дашагрива схватить Ханумана.",
82	      "commentary": {
83	        "tilaka": "संवृताकारो निगृहीतान्तर्गतभयः । उत्तमां मतिं धैर्यविषयाम् ।। 5.46.1,2 ।।\n\nहनूमद्ग्रहणे सन्दिदेश । व्यग्रान्सर्वत्र कार्ये त्वरावतः",
84	        "bhusana": "सन्दिदेश दशग्रीवो वीरान्नयविशारदान् ।\n\nहनुमद्ग्रहणव्यग्रान् वायुवेगसमान् युधि"
85	      },
