157	      }
158	    },
159	    {
160	      "verse_id": "5.46.6",
161	      "sarga": 46,
162	      "verse": "6",
163	      "ambiguous_marker": false,
164	      "sanskrit_iast": "na hy ahaṃ taṃ kapiṃ manye karmaṇā prati tarkayan । sarvathā tan mahad bhūtaṃ mahābalaparigraham ॥6॥",
165	      "leonov_ru": "Ибо размышляя о [его] действиях, не думаю я, что это обезьяна. Судя по всему, это великое существо, наделенное огромной силой.",
166	      "commentary": {
167	        "tilaka": "यत्तैर्भाव्यमित्यत्र हेतुमाह-- नहीति । तस्य कर्मणां तं प्रति तर्कयंस्तं कपिं न मन्ये । किं तर्हि मन्यसे तत्राह-- सर्वथेति ।। 5.46.6,7 ।।\n\nमहतो भूतस्येह कः प्रसङ्गस्तत्राह-- भवेदिति । सनागेति नागादिसहिता देवादय इत्यर्थः",
168	        "bhusana": "न ह्यहं तं कपिं मन्ये कर्मणा प्रतितर्कयन् ।\n\nसर्वथा तन्महद्भूतं महाबलपरिग्रहम् ।\n\nभवेदिन्द्रेण वा सृष्टमस्मदर्थं तपोबलात्",
169	        "siromani": "अतिप्रयत्नेन स्थितौ हेतुमाह नहीति । महाबलपरिग्रहं वृतं हतसेनायाः परिग्राहकं विध्वंसकमित्यर्थः । तं कर्मणा तत्क्रियया प्रतितर्कयन्नहं कपिं न मन्ये किंतु भूतमत्र प्राप्तं तत् सर्वथा महदतिश्रेष्ठं मन्ये"
170	      },
171	      "pratika_check": {
