178	        "bhusana": {
179	          "pratika_iast": "na hyahan tan kapin",
180	          "matches_verse": true
181	        },
182	        "siromani": {
183	          "pratika_iast": "atiprayatnena sthitau hetunaha nahiti",
184	          "matches_verse": true
