188	    {
189	      "verse_id": "5.46.7",
190	      "sarga": 46,
191	      "verse": "7",
192	      "ambiguous_marker": false,
193	      "sanskrit_iast": "vānaro 'yam iti jñātvā na hi śuddhyati me manaḥ । naivāhaṃ taṃ kapiṃ manye yatheyaṃ prastutā kathā ॥7॥",
194	      "leonov_ru": "Узнав, что это обезьяна, не удовлетворен мой ум. Не думаю я, что это обезьяна, как о ней было рассказано.",
195	      "commentary": {
196	        "siromani": "ननु तर्हि को ऽयमित्यत आह भवेदिति । अस्मदर्थम् अस्मद्विनाशार्थं तपोबलादिन्द्रेण सृष्टं भवेत् । अर्धं पृथक् । तत्र हेतुं वदन्नाह सेति । ये नागादिसहिता महर्षयः मया प्रहितैः प्रेषितैर्युष्माभिः सह एककालावच्छेदेन विनिर्जिताः तैर्नो ऽस्माकं किंचित् व्यलीकमप्रियमवश्यं विधातव्यम् । सार्धश्लोक एकान्वयी ।। 5.46.7,8 ।।\n\nतदिति । तदिन्द्रसृष्टमेव अत्र संदेहो न अतो महाबलपरिग्रहाः अत एव सवाजिरथमातङ्गाः यूयं यात प्रसह्य हठात् परिगृह्यताम् । नन्वेकाकिनस्तस्यार्थे किमर्थमेवं प्रेषणमित्यत आह धीरपराक्रमः कपिर्भवद्भिर्न्नावमान्यः तुच्छबुद्ध्या नानादर्तव्यः । एतेन तस्य महाबलत्वं सूचितम् । श्लोकद्वयं संमिलितान्वयि ।। 5.46.9,10 ।।\n\nननु वानररूपे कथमेवं पराक्रम इत्यत आह दृष्टा इति । विपुलविक्रमाः वाल्यादयो हरयः मया पूर्वं दृष्टाः । सार्धश्लोक एकान्वयी"
197	      },
198	      "pratika_check": {
199	        "siromani": {
200	          "pratika_iast": "nanu tarhi ko yanityata",
201	          "matches_verse": true
202	        }
203	      }
204	    },
205	    {
206	      "verse_id": "5.46.8",
207	      "sarga": 46,
208	      "verse": "8",
209	      "ambiguous_marker": false,
210	      "sanskrit_iast": "bhaved indreṇa vā sṛṣṭam asmadarthaṃ tapobalāt । sanāgayakṣagandharvā devāsuramaharṣayaḥ ॥8॥",
211	      "leonov_ru": "Или, может быть, Индрой сотворен [он] посредством аскетической силы, ради нас (ради нашей погибели). Девы, асуры и великие риши вместе с нагами, якшами и гандхарвами,",
212	      "commentary": {
213	        "bhusana": "सनागयक्षगन्धर्वा देवासुरमहर्षयः ।\n\nयुष्माभिः सहितैः सर्वैर्मया सह विनिर्जिताः"
214	      },
215	      "pratika_check": {
216	        "bhusana": {
217	          "pratika_iast": "sanagayaksagandharva devasuranaharsayah",
218	          "matches_verse": true
219	        }
220	      }
221	    },
222	    {
223	      "verse_id": "5.46.9",
224	      "sarga": 46,
225	      "verse": "9",
226	      "ambiguous_marker": false,
227	      "sanskrit_iast": "yuṣmābhiḥ sahitaiḥ sarvair mayā saha vinirjitāḥ । tair avaśyaṃ vidhātavyaṃ vyalīkaṃ kiṃ cid eva naḥ ॥9॥",
228	      "leonov_ru": "Вместе с вами со всеми мной были побеждены. Ими, несомненно, должно было быть предпринято нечто, неприятное нам.",
229	      "commentary": {
230	        "bhusana": "तैरवश्यं विधातव्यं व्यलीकं किंचिदेव नः ।\n\nतदेव नात्र सन्देहः प्रसह्य परिगृह्यताम्\nव्यलीकम् अप्रियम्",
231	        "tilaka": "प्रहितैः सर्वैर्युष्माभिः सह मया विनिर्जिताः, अतस्तैरवश्यं नो ऽस्माकं किञ्चिद्व्यलीकमप्रियं विधातव्यं विधातुं प्राप्तकालम्\nसर्वथा महद्भूतमित्यत्र हेतुं निश्चायकमाह-- दृष्टा इति"
232	      },
233	      "pratika_check": {
234	        "bhusana": {
235	          "pratika_iast": "tairavasyan vidhatavyan vyalikan kincideva",
236	          "matches_verse": true
237	        },
238	        "tilaka": {
239	          "pratika_iast": "prahitaih sarvairyusnabhih saha naya",
240	          "matches_verse": true
241	        }
242	      }
243	    },
244	    {
245	      "verse_id": "5.46.10",
246	      "sarga": 46,
