import json, sys

sarga = int(sys.argv[1])
root = r"C:\Users\user\Documents\GitHub\CommentaryStrategies\.claude\worktrees\h268-lp-camera-ready"

out = {"leonov": [], "sundara": []}

with open(root + r"\data\leonov_own_notes.json", encoding="utf-8") as f:
    leonov = json.load(f)
if isinstance(leonov, dict):
    # find the list
    for k, v in leonov.items():
        if isinstance(v, list):
            leonov = v
            break
for n in leonov:
    if n.get("sarga") == sarga:
        out["leonov"].append(n)

with open(root + r"\data\sundara_commentary_to_add.json", encoding="utf-8") as f:
    sundara = json.load(f)
if isinstance(sundara, dict):
    for k, v in sundara.items():
        if isinstance(v, list):
            sundara = v
            break
prefix = f"V.{sarga}."
for n in sundara:
    sh = n.get("shloka", "")
    if isinstance(sh, str) and sh.startswith(prefix):
        out["sundara"].append(n)

with open(sys.argv[2], "w", encoding="utf-8") as f:
    json.dump(out, f, ensure_ascii=False, indent=2)

print(f"sarga {sarga}: leonov={len(out['leonov'])} sundara={len(out['sundara'])}", file=sys.stderr)
